/**
* Name: ThirteenAdjacentDigit.c (Project Euler - Problem 8)
* Purpose: Find the largest product made by 13 digits in a number of 1000 digits
* Author: CplusX-Builder
* Date: October 2026
**/

#include<stdio.h>
#include"ProjectEuler.h"

#define NUMBER_OF_DIGITS 1000
#define THIRTEEN_DIGITS_COMBINATION 77
#define PLACE_HOLDER_ARRAY_SIZE 13

int placeHolder[13]; //holds each 13 digits at a time.
char bigNumber[NUMBER_OF_DIGITS + 1] = "";
int i = 0;

void insertingInArray(void);
long int product(void);
void writeOnFile(long int x);

int main(void)
{
    for (int n = 0; n < THIRTEEN_DIGITS_COMBINATION; n++)
    {
        for (int m = 0; m < PLACE_HOLDER_ARRAY_SIZE; m++)
        {
            insertingInArray();
        }
        writeOnFile(product());
    }
return 0;
}

void insertingInArray(void)
{
        placeHolder[i] = changeCharacterToNumber(bigNumber[i]);
        i = i + 1;
}

long int product(void)
{
    long int productOfArray = 1;
    for (int j = 0; j < PLACE_HOLDER_ARRAY_SIZE; j++)
    {
        productOfArray = placeHolder[j] * productOfArray;
    }
return productOfArray;
}

void writeOnFile(long int x)
{
    FILE *filePointer;
    filePointer = fopen("databaseOfProducts.txt", "w");

    if (filePointer == NULL)
    {
        fclose(filePointer);
    }
    else
    {
        fprintf(filePointer, "%ld\n", x);
    }
}








